export function getDestinationById(id: string): Destination | undefined {
  if (!id) return undefined;
  const raw = id.trim().toLowerCase();
  const clean = raw.replace(/[^a-z0-9]/g, '');
  const cleanWithUnderscore = raw.replace(/[^a-z0-9]/g, '_');
  
  return INITIAL_DESTINATIONS.find((d) => {
    const dId = d.id.toLowerCase();
    const dIdClean = dId.replace(/[^a-z0-9]/g, '');
    const dName = d.name.toLowerCase();
    const dNameClean = dName.replace(/[^a-z0-9]/g, '');
    
    return (
      dId === raw ||
      dId === cleanWithUnderscore ||
      dIdClean === clean ||
      dName === raw ||
      dNameClean === clean ||
      (clean.length >= 4 && (dNameClean.startsWith(clean) || clean.startsWith(dNameClean)))
    );
  });
}

export function getAllCategories(): string[] {
  const set = new Set<string>();
  INITIAL_DESTINATIONS.forEach((d) => {
    set.add(d.category);
    d.secondaryCategories.forEach((sc) => set.add(sc));
  });
  return ['All', ...Array.from(set).sort()];
}

export function getAllStates(): string[] {
  const set = new Set<string>();
  INITIAL_DESTINATIONS.forEach((d) => set.add(d.state));
  return ['All', ...Array.from(set).sort()];
}

export function getAllRegions(): string[] {
  const set = new Set<string>();
  INITIAL_DESTINATIONS.forEach((d) => set.add(d.region));
  return ['All', ...Array.from(set).sort()];
}
